insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning', 'Classical conditioning (also respondent conditioning and Pavlovian conditioning) is a behavioral procedure in which a biologically potent stimulus (e.g. food, a puff of air on the eye) is paired with a neutral stimulus (e.g. the sound of a musical triangle). The term classical conditioning refers to the process of an automatic, conditioned response that is paired with a specific stimulus. It is essentially equivalent to a signal. Ivan Pavlov, the Russian physiologist, studied classical conditioning with detailed experiments with dogs, and published the experimental results in 1897. In the study of digestion, Pavlov observed that the experimental dogs salivated when fed red meat. Pavlovian conditioning is distinct from operant conditioning (instrumental conditioning), through which the strength of a voluntary behavior is modified, either by reinforcement or by punishment. However, classical conditioning can affect operant conditioning; classically conditioned stimuli can reinforce operant responses. Classical conditioning is a basic behavioral mechanism, and its neural substrates are now beginning to be understood. Though it is sometimes hard to distinguish classical conditioning from other forms of associative learning (e.g., instrumental learning and human associative memory); a number of observations differentiate them, especially the contingencies whereby learning occurs.', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Classical conditioning (also respondent conditioning and Pavlovian conditioning) is a behavioral procedure in which a biologically potent stimulus (e.g. food, a puff of air on the eye) is paired with a neutral stimulus (e.g. the sound of a musical triangle). The term classical conditioning refers to the process of an automatic, conditioned response that is paired with a specific stimulus. It is essentially equivalent to a signal. Ivan Pavlov, the Russian physiologist, studied classical conditioning with detailed experiments with dogs, and published the experimental results in 1897. In the study of digestion, Pavlov observed that the experimental dogs salivated when fed red meat. Pavlovian conditioning is distinct from operant conditioning (instrumental conditioning), through which the strength of a voluntary behavior is modified, either by reinforcement or by punishment. However, classical conditioning can affect operant conditioning; classically conditioned stimuli can reinforce operant responses. Classical conditioning is a basic behavioral mechanism, and its neural substrates are now beginning to be understood. Though it is sometimes hard to distinguish classical conditioning from other forms of associative learning (e.g., instrumental learning and human associative memory); a number of observations differentiate them, especially the contingencies whereby learning occurs.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning', 'Together with operant conditioning, classical conditioning became the foundation of behaviorism, a school of psychology which was dominant in the mid-20th century and is still an important influence on the practice of psychological therapy and the study of animal behavior. Classical conditioning has been applied in other areas as well. For example, it may affect the body''s response to psychoactive drugs, the regulation of hunger, research on the neural basis of learning and memory, and in certain social phenomena such as the false consensus effect.', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Together with operant conditioning, classical conditioning became the foundation of behaviorism, a school of psychology which was dominant in the mid-20th century and is still an important influence on the practice of psychological therapy and the study of animal behavior. Classical conditioning has been applied in other areas as well. For example, it may affect the body''s response to psychoactive drugs, the regulation of hunger, research on the neural basis of learning and memory, and in certain social phenomena such as the false consensus effect.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning: Definition', 'Classical conditioning is a type of learning which occurs when a conditioned stimulus (CS) is paired with an unconditioned stimulus (US). Usually, the conditioned stimulus is a neutral stimulus (e.g., the sound of a tuning fork), the unconditioned stimulus is biologically potent (e.g., the taste of food) and the unconditioned response (UR) to the unconditioned stimulus is an innate reflex response (e.g., salivation). After pairing is repeated, the organism exhibits a conditioned response (CR) to the conditioned stimulus when the conditioned stimulus is presented alone. (A conditioned response may occur after only one pairing.) Thus, unlike the UR, the CR is acquired through experience, and it is also less permanent than the UR. Usually the conditioned response is similar to the unconditioned response, but sometimes it is quite different. For this and other reasons, most learning theorists suggest that the conditioned stimulus comes to signal or predict the unconditioned stimulus, and go on to analyse the consequences of this signal. Robert A. Rescorla provided a clear summary of this change in thinking, and its implications, in his 1988 article "Pavlovian conditioning: It''s not what you think it is". Despite its widespread acceptance, Rescorla''s theory also has shortcomings.', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Classical conditioning is a type of learning which occurs when a conditioned stimulus (CS) is paired with an unconditioned stimulus (US). Usually, the conditioned stimulus is a neutral stimulus (e.g., the sound of a tuning fork), the unconditioned stimulus is biologically potent (e.g., the taste of food) and the unconditioned response (UR) to the unconditioned stimulus is an innate reflex response (e.g., salivation). After pairing is repeated, the organism exhibits a conditioned response (CR) to the conditioned stimulus when the conditioned stimulus is presented alone. (A conditioned response may occur after only one pairing.) Thus, unlike the UR, the CR is acquired through experience, and it is also less permanent than the UR. Usually the conditioned response is similar to the unconditioned response, but sometimes it is quite different. For this and other reasons, most learning theorists suggest that the conditioned stimulus comes to signal or predict the unconditioned stimulus, and go on to analyse the consequences of this signal. Robert A. Rescorla provided a clear summary of this change in thinking, and its implications, in his 1988 article "Pavlovian conditioning: It''s not what you think it is". Despite its widespread acceptance, Rescorla''s theory also has shortcomings.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning: Definition', 'A false-positive involving classical conditioning from chance (where the unconditioned stimulus has the same chance of happening with or without the conditioned stimulus) has been proven to be improbable in successfully conditioning a response. The element of contingency has been further tested and is said to have "outlived any usefulness in the analysis of conditioning." Classical conditioning differs from operant or instrumental conditioning: in classical conditioning, behaviors are modified through the association of stimuli as described above, whereas in operant conditioning behaviors are modified by the effect they produce (i.e., reward or punishment).', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'A false-positive involving classical conditioning from chance (where the unconditioned stimulus has the same chance of happening with or without the conditioned stimulus) has been proven to be improbable in successfully conditioning a response. The element of contingency has been further tested and is said to have "outlived any usefulness in the analysis of conditioning." Classical conditioning differs from operant or instrumental conditioning: in classical conditioning, behaviors are modified through the association of stimuli as described above, whereas in operant conditioning behaviors are modified by the effect they produce (i.e., reward or punishment).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning: Evaluative conditioning', 'Evaluative conditioning is a form of classical conditioning, in that it involves a change in the responses to the conditioned stimulus that results from pairing the conditioned stimulus with an unconditioned stimulus. Whereas classic conditioning can refer to a change in any type of response, evaluative conditioning concerns only a change in the evaluative responses to the conditioned stimulus, that is, a change in the liking of the conditioned stimulus. Evaluative conditioning is defined as a change in the association of a stimulus that is due to the pairing of that stimulus with another positive or negative stimulus. The first stimulus is often referred to as the conditioned stimulus and the second stimulus as the unconditioned stimulus. A conditioned stimulus becomes more positive when it has been paired with a positive unconditioned stimulus and more negative when it has been paired with a negative unconditioned stimulus. Evaluative conditioning thus refers to attitude formation or change toward an object due to that object''s mere co-occurrence with another object.', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Evaluative conditioning is a form of classical conditioning, in that it involves a change in the responses to the conditioned stimulus that results from pairing the conditioned stimulus with an unconditioned stimulus. Whereas classic conditioning can refer to a change in any type of response, evaluative conditioning concerns only a change in the evaluative responses to the conditioned stimulus, that is, a change in the liking of the conditioned stimulus. Evaluative conditioning is defined as a change in the association of a stimulus that is due to the pairing of that stimulus with another positive or negative stimulus. The first stimulus is often referred to as the conditioned stimulus and the second stimulus as the unconditioned stimulus. A conditioned stimulus becomes more positive when it has been paired with a positive unconditioned stimulus and more negative when it has been paired with a negative unconditioned stimulus. Evaluative conditioning thus refers to attitude formation or change toward an object due to that object''s mere co-occurrence with another object.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning: Evaluative conditioning', 'A classic example of the formation of attitudes through conditioning is the 1958 experiment by Staats and Staats. Subjects first were asked to learn a list of words that were presented visually, and were tested on their learning of the list. They then did the same with a list of words presented orally, all of which set the stage for the critical phase of the experiment which was portrayed as an assessment of subjects'' ability to learn via both visual and auditory channels at once. During this phase, subjects were exposed visually to a set of nationality names, specifically Dutch and Swedish. Approximately one second after the nationality appeared on the screen, the experimenter announced a word aloud. Most of these latter words, none of which were repeated, were neutral (e.g., chair, with, twelve). Included, however, were a few positive words (e.g., gift, sacred, happy) and a few negative words (e.g., bitter, ugly, failure). These words were systematically paired with the two conditional stimuli nationalities such that one always appeared with positive words and the other with negative words. Thus, the conditioning trials were embedded within a stream of visually presented nationality names and orally presented words. When the conditioning phase was completed, the subjects were first asked to recall the words that had been presented visually and then to evaluate them, presumably because how they felt about those words might have affected their learning. The conditioning was successful. The nationality that had been paired with the more positive unconditional stimuli was rated as more pleasant than the one paired with the negative unconditional stimuli.', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'A classic example of the formation of attitudes through conditioning is the 1958 experiment by Staats and Staats. Subjects first were asked to learn a list of words that were presented visually, and were tested on their learning of the list. They then did the same with a list of words presented orally, all of which set the stage for the critical phase of the experiment which was portrayed as an assessment of subjects'' ability to learn via both visual and auditory channels at once. During this phase, subjects were exposed visually to a set of nationality names, specifically Dutch and Swedish. Approximately one second after the nationality appeared on the screen, the experimenter announced a word aloud. Most of these latter words, none of which were repeated, were neutral (e.g., chair, with, twelve). Included, however, were a few positive words (e.g., gift, sacred, happy) and a few negative words (e.g., bitter, ugly, failure). These words were systematically paired with the two conditional stimuli nationalities such that one always appeared with positive words and the other with negative words. Thus, the conditioning trials were embedded within a stream of visually presented nationality names and orally presented words. When the conditioning phase was completed, the subjects were first asked to recall the words that had been presented visually and then to evaluate them, presumably because how they felt about those words might have affected their learning. The conditioning was successful. The nationality that had been paired with the more positive unconditional stimuli was rated as more pleasant than the one paired with the negative unconditional stimuli.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning: Pavlov''s research', 'The best-known and most thorough early work on classical conditioning was done by Ivan Pavlov, although Edwin Twitmyer published some related findings a year earlier. During his research on the physiology of digestion in dogs, Pavlov developed a procedure that enabled him to study the digestive processes of animals over long periods of time. He redirected the animals'' digestive fluids outside the body, where they could be measured. Pavlov noticed that his dogs began to salivate in the presence of the technician who normally fed them, rather than simply salivating in the presence of food. Pavlov called the dogs'' anticipatory salivation "psychic secretion". Putting these informal observations to an experimental test, Pavlov presented a stimulus (e.g. the sound of a metronome) and then gave the dog food; after a few repetitions, the dogs started to salivate in response to the stimulus. Pavlov concluded that if a particular stimulus in the dog''s surroundings was present when the dog was given food then that stimulus could become associated with food and cause salivation on its own.', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'The best-known and most thorough early work on classical conditioning was done by Ivan Pavlov, although Edwin Twitmyer published some related findings a year earlier. During his research on the physiology of digestion in dogs, Pavlov developed a procedure that enabled him to study the digestive processes of animals over long periods of time. He redirected the animals'' digestive fluids outside the body, where they could be measured. Pavlov noticed that his dogs began to salivate in the presence of the technician who normally fed them, rather than simply salivating in the presence of food. Pavlov called the dogs'' anticipatory salivation "psychic secretion". Putting these informal observations to an experimental test, Pavlov presented a stimulus (e.g. the sound of a metronome) and then gave the dog food; after a few repetitions, the dogs started to salivate in response to the stimulus. Pavlov concluded that if a particular stimulus in the dog''s surroundings was present when the dog was given food then that stimulus could become associated with food and cause salivation on its own.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Classical conditioning: Terminology', 'In Pavlov''s experiments the unconditioned stimulus (US) was the food because its effects did not depend on previous experience. The metronome''s sound is originally a neutral stimulus (NS) because it does not elicit salivation in the dogs. After conditioning, the metronome''s sound becomes the conditioned stimulus (CS) or conditional stimulus; because its effects depend on its association with food. Likewise, the responses of the dog follow the same conditioned-versus-unconditioned arrangement. The conditioned response (CR) is the response to the conditioned stimulus, whereas the unconditioned response (UR) corresponds to the unconditioned stimulus. Pavlov reported many basic facts about conditioning; for example, he found that learning occurred most rapidly when the interval between the CS and the appearance of the US was relatively short. As noted earlier, it is often thought that the conditioned response is a replica of the unconditioned response, but Pavlov noted that saliva produced by the CS differs in composition from that produced by the US. In fact, the CR may be any new response to the previously neutral CS that can be clearly linked to experience with the conditional relationship of CS and US. It was also thought that repeated pairings are necessary for conditioning to emerge, but many CRs can be learned with a single trial, especially in fear conditioning and taste aversion learning.', 'Wikipedia: Classical conditioning', 'https://en.wikipedia.org/w/index.php?title=Classical_conditioning&oldid=1380298957', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'In Pavlov''s experiments the unconditioned stimulus (US) was the food because its effects did not depend on previous experience. The metronome''s sound is originally a neutral stimulus (NS) because it does not elicit salivation in the dogs. After conditioning, the metronome''s sound becomes the conditioned stimulus (CS) or conditional stimulus; because its effects depend on its association with food. Likewise, the responses of the dog follow the same conditioned-versus-unconditioned arrangement. The conditioned response (CR) is the response to the conditioned stimulus, whereas the unconditioned response (UR) corresponds to the unconditioned stimulus. Pavlov reported many basic facts about conditioning; for example, he found that learning occurred most rapidly when the interval between the CS and the appearance of the US was relatively short. As noted earlier, it is often thought that the conditioned response is a replica of the unconditioned response, but Pavlov noted that saliva produced by the CS differs in composition from that produced by the US. In fact, the CR may be any new response to the previously neutral CS that can be clearly linked to experience with the conditional relationship of CS and US. It was also thought that repeated pairings are necessary for conditioning to emerge, but many CRs can be learned with a single trial, especially in fear conditioning and taste aversion learning.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning', 'Operant conditioning, also called instrumental conditioning, is a learning process in which voluntary behaviors are modified by association with the addition (or removal) of reward or aversive stimuli. The frequency or duration of the behavior may increase through reinforcement or decrease through punishment or extinction.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Operant conditioning, also called instrumental conditioning, is a learning process in which voluntary behaviors are modified by association with the addition (or removal) of reward or aversive stimuli. The frequency or duration of the behavior may increase through reinforcement or decrease through punishment or extinction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning: Origins', 'Operant conditioning originated with Edward Thorndike, whose law of effect theorised that behaviors arise as a result of consequences as satisfying or discomforting. In the 20th century, operant conditioning was studied by behavioral psychologists, who believed that much of mind and behaviour is explained through environmental conditioning. Reinforcements are environmental stimuli that increase behaviors, whereas punishments are stimuli that decrease behaviors. Both kinds of stimuli can be further categorised into positive and negative stimuli, which respectively involve the addition or removal of environmental stimuli. Operant conditioning differs from classical conditioning in both mechanism and outcome. While classical conditioning pairs stimuli to produce involuntary, reflexive behaviors (like salivating at food), operant conditioning shapes voluntary behaviors through their consequences. Actions followed by rewards tend to be repeated, while those followed by negative outcomes diminish. The study of animal learning in the 20th century was dominated by the analysis of these two sorts of learning, and they are still at the core of behavior analysis. They have also been applied to the study of social psychology, helping to clarify certain phenomena such as the false consensus effect.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Operant conditioning originated with Edward Thorndike, whose law of effect theorised that behaviors arise as a result of consequences as satisfying or discomforting. In the 20th century, operant conditioning was studied by behavioral psychologists, who believed that much of mind and behaviour is explained through environmental conditioning. Reinforcements are environmental stimuli that increase behaviors, whereas punishments are stimuli that decrease behaviors. Both kinds of stimuli can be further categorised into positive and negative stimuli, which respectively involve the addition or removal of environmental stimuli. Operant conditioning differs from classical conditioning in both mechanism and outcome. While classical conditioning pairs stimuli to produce involuntary, reflexive behaviors (like salivating at food), operant conditioning shapes voluntary behaviors through their consequences. Actions followed by rewards tend to be repeated, while those followed by negative outcomes diminish. The study of animal learning in the 20th century was dominated by the analysis of these two sorts of learning, and they are still at the core of behavior analysis. They have also been applied to the study of social psychology, helping to clarify certain phenomena such as the false consensus effect.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning: Origins of operant behavior: operant variability', 'Operant behavior is said to be "emitted"; that is, initially it is not elicited by any particular stimulus. Thus one may ask why it happens in the first place. The answer to this question is like Darwin''s answer to the question of the origin of a "new" bodily structure, namely, variation and selection. Similarly, the behavior of an individual varies from moment to moment, in such aspects as the specific motions involved, the amount of force applied, or the timing of the response. Variations that lead to reinforcement are strengthened, and if reinforcement is consistent, the behavior tends to remain stable. However, behavioral variability can itself be altered through the manipulation of certain variables.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Operant behavior is said to be "emitted"; that is, initially it is not elicited by any particular stimulus. Thus one may ask why it happens in the first place. The answer to this question is like Darwin''s answer to the question of the origin of a "new" bodily structure, namely, variation and selection. Similarly, the behavior of an individual varies from moment to moment, in such aspects as the specific motions involved, the amount of force applied, or the timing of the response. Variations that lead to reinforcement are strengthened, and if reinforcement is consistent, the behavior tends to remain stable. However, behavioral variability can itself be altered through the manipulation of certain variables.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning: Modifying operant behavior: reinforcement and punishment', 'Reinforcement and punishment are the core tools through which operant behavior is modified. These terms are defined by their effect on behavior. "Positive" and "negative" refer to whether a stimulus was added or removed, respectively. Similarly, "reinforcement" and "punishment" refer to the future frequency of the behavior. Reinforcement describes a consequence that makes a behavior occur more often in the future, whereas punishment is a consequence that makes a behavior occur less often. Positive reinforcement occurs when a behavior (response) results in a desired stimulus being added and increases the frequency of that behavior in the future. Example: if a rat in a Skinner box gets food when it presses a lever, its rate of pressing will go up. Pressing the lever was positively reinforced. Negative reinforcement (a.k.a. escape) occurs when a behavior (response) is followed by the removal of an aversive stimulus, thereby increasing the original behavior''s frequency. Example: A child is afraid of loud noises at a fireworks display. They put on a pair of headphones, and they can no longer hear the fireworks. The next time the child sees fireworks, they put on a pair of headphones. Putting on headphones was negatively reinforced.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Reinforcement and punishment are the core tools through which operant behavior is modified. These terms are defined by their effect on behavior. "Positive" and "negative" refer to whether a stimulus was added or removed, respectively. Similarly, "reinforcement" and "punishment" refer to the future frequency of the behavior. Reinforcement describes a consequence that makes a behavior occur more often in the future, whereas punishment is a consequence that makes a behavior occur less often. Positive reinforcement occurs when a behavior (response) results in a desired stimulus being added and increases the frequency of that behavior in the future. Example: if a rat in a Skinner box gets food when it presses a lever, its rate of pressing will go up. Pressing the lever was positively reinforced. Negative reinforcement (a.k.a. escape) occurs when a behavior (response) is followed by the removal of an aversive stimulus, thereby increasing the original behavior''s frequency. Example: A child is afraid of loud noises at a fireworks display. They put on a pair of headphones, and they can no longer hear the fireworks. The next time the child sees fireworks, they put on a pair of headphones. Putting on headphones was negatively reinforced.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning: Modifying operant behavior: reinforcement and punishment', 'Positive punishment (also referred to as "punishment by contingent stimulation") occurs when a behavior (response) is followed by an aversive stimulus which makes the behavior less likely to occur in the future. Example: A child touches a hot stove and burns his hand. The next time he sees a stove, he does not touch it. Touching the stove was positively punished. Negative punishment (penalty) (also called "punishment by contingent withdrawal") occurs when a behavior (response) is followed by the removal of a stimulus, and the behavior is less likely to occur in the future. Example: When an employee puts their lunch in a communal refrigerator, it gets stolen before break time. The next time the employee brings a lunch to work, they do not put it in the refrigerator. Putting the lunch in the refrigerator was negatively punished. Extinction is a consequence strategy that occurs when a previously reinforced behavior is no longer reinforced with either positive or negative reinforcement. During extinction the behavior becomes less probable. Occasional reinforcement can lead to an even longer delay before behavior extinction due to the learning factor of repeated instances becoming necessary to get reinforcement, when compared with reinforcement being given at each opportunity before extinction.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Positive punishment (also referred to as "punishment by contingent stimulation") occurs when a behavior (response) is followed by an aversive stimulus which makes the behavior less likely to occur in the future. Example: A child touches a hot stove and burns his hand. The next time he sees a stove, he does not touch it. Touching the stove was positively punished. Negative punishment (penalty) (also called "punishment by contingent withdrawal") occurs when a behavior (response) is followed by the removal of a stimulus, and the behavior is less likely to occur in the future. Example: When an employee puts their lunch in a communal refrigerator, it gets stolen before break time. The next time the employee brings a lunch to work, they do not put it in the refrigerator. Putting the lunch in the refrigerator was negatively punished. Extinction is a consequence strategy that occurs when a previously reinforced behavior is no longer reinforced with either positive or negative reinforcement. During extinction the behavior becomes less probable. Occasional reinforcement can lead to an even longer delay before behavior extinction due to the learning factor of repeated instances becoming necessary to get reinforcement, when compared with reinforcement being given at each opportunity before extinction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning: Modifying operant behavior: reinforcement and punishment', 'A study suggests that tactile feedback, such as haptic vibrations from mobile devices, can function as secondary reinforcers (i.e., learned rewards that acquire reinforcing value through association), strengthening consumer behaviors such as online purchasing.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'A study suggests that tactile feedback, such as haptic vibrations from mobile devices, can function as secondary reinforcers (i.e., learned rewards that acquire reinforcing value through association), strengthening consumer behaviors such as online purchasing.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning: Schedules of reinforcement', 'Schedules of reinforcement are rules that control the delivery of reinforcement. The rules specify either the time that reinforcement is to be made available, or the number of responses to be made, or both. Many rules are possible, but the following are the most basic and commonly used Fixed interval schedule: Reinforcement occurs following the first response after a fixed time has elapsed after the previous reinforcement. This schedule yields a "break-run" pattern of response; that is, after training on this schedule, the organism typically pauses after reinforcement, and then begins to respond rapidly as the time for the next reinforcement approaches. Variable interval schedule: Reinforcement occurs following the first response after a variable time has elapsed from the previous reinforcement. This schedule typically yields a relatively steady rate of response that varies with the average time between reinforcements. Fixed ratio schedule: Reinforcement occurs after a fixed number of responses have been emitted since the previous reinforcement. An organism trained on this schedule typically pauses for a while after a reinforcement and then responds at a high rate. If the response requirement is low there may be no pause; if the response requirement is high the organism may quit responding altogether.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Schedules of reinforcement are rules that control the delivery of reinforcement. The rules specify either the time that reinforcement is to be made available, or the number of responses to be made, or both. Many rules are possible, but the following are the most basic and commonly used Fixed interval schedule: Reinforcement occurs following the first response after a fixed time has elapsed after the previous reinforcement. This schedule yields a "break-run" pattern of response; that is, after training on this schedule, the organism typically pauses after reinforcement, and then begins to respond rapidly as the time for the next reinforcement approaches. Variable interval schedule: Reinforcement occurs following the first response after a variable time has elapsed from the previous reinforcement. This schedule typically yields a relatively steady rate of response that varies with the average time between reinforcements. Fixed ratio schedule: Reinforcement occurs after a fixed number of responses have been emitted since the previous reinforcement. An organism trained on this schedule typically pauses for a while after a reinforcement and then responds at a high rate. If the response requirement is low there may be no pause; if the response requirement is high the organism may quit responding altogether.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Operant conditioning: Schedules of reinforcement', 'Variable ratio schedule: Reinforcement occurs after a variable number of responses have been emitted since the previous reinforcement. This schedule typically yields a very high, persistent rate of response. Continuous reinforcement: Reinforcement occurs after each response. Organisms typically respond as rapidly as they can, given the time taken to obtain and consume reinforcement, until they are satiated.', 'Wikipedia: Operant conditioning', 'https://en.wikipedia.org/w/index.php?title=Operant_conditioning&oldid=1374182721', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Variable ratio schedule: Reinforcement occurs after a variable number of responses have been emitted since the previous reinforcement. This schedule typically yields a very high, persistent rate of response. Continuous reinforcement: Reinforcement occurs after each response. Organisms typically respond as rapidly as they can, given the time taken to obtain and consume reinforcement, until they are satiated.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement', 'In behavioral psychology, reinforcement refers to consequences that increase the likelihood of an organism''s future behavior, typically in the presence of a particular antecedent stimulus. For example, a rat can be trained to push a lever to receive food whenever a light is turned on; in this example, the light is the antecedent stimulus, the lever pushing is the operant behavior, and the food is the reinforcer. Likewise, a student that receives attention and praise when answering a teacher''s question will be more likely to answer future questions in class; the teacher''s question is the antecedent, the student''s response is the behavior, and the praise and attention are the reinforcements. Punishment is the inverse to reinforcement, referring to any behavior that decreases the likelihood that a response will occur. In operant conditioning terms, punishment does not need to involve any type of pain, fear, or physical actions; even a brief spoken expression of disapproval is a type of punishment. Consequences that lead to appetitive behavior such as subjective "wanting" and "liking" (desire and pleasure) function as rewards or positive reinforcement. There is also negative reinforcement, which involves taking away an undesirable stimulus. An example of negative reinforcement would be taking an aspirin to relieve a headache.', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'In behavioral psychology, reinforcement refers to consequences that increase the likelihood of an organism''s future behavior, typically in the presence of a particular antecedent stimulus. For example, a rat can be trained to push a lever to receive food whenever a light is turned on; in this example, the light is the antecedent stimulus, the lever pushing is the operant behavior, and the food is the reinforcer. Likewise, a student that receives attention and praise when answering a teacher''s question will be more likely to answer future questions in class; the teacher''s question is the antecedent, the student''s response is the behavior, and the praise and attention are the reinforcements. Punishment is the inverse to reinforcement, referring to any behavior that decreases the likelihood that a response will occur. In operant conditioning terms, punishment does not need to involve any type of pain, fear, or physical actions; even a brief spoken expression of disapproval is a type of punishment. Consequences that lead to appetitive behavior such as subjective "wanting" and "liking" (desire and pleasure) function as rewards or positive reinforcement. There is also negative reinforcement, which involves taking away an undesirable stimulus. An example of negative reinforcement would be taking an aspirin to relieve a headache.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement', 'Reinforcement is an important component of operant conditioning and behavior modification. The concept has been applied in a variety of practical areas, including parenting, coaching, therapy, self-help, education, and management.', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Reinforcement is an important component of operant conditioning and behavior modification. The concept has been applied in a variety of practical areas, including parenting, coaching, therapy, self-help, education, and management.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement: Terminology', 'In the behavioral sciences, the terms positive and negative refer, when used in their strict technical sense, to the nature of the action performed by the conditioner rather than to the responding operant''s evaluation of that action and its consequence(s). Positive actions are those that add a factor, be it pleasant or unpleasant, to the environment, whereas negative actions are those that remove or withhold from the environment a factor of either type. In turn, the strict sense of reinforcement refers only to reward-based conditioning; the introduction of unpleasant factors and the removal or withholding of pleasant factors are instead referred to as punishment, which when used in its strict sense thus stands in contradistinction to reinforcement. Thus, positive reinforcement refers to the addition of a pleasant factor, positive punishment (sometimes called Type I punishment) refers to the addition of an unpleasant factor, negative reinforcement refers to the removal or withholding of an unpleasant factor, and negative punishment (Type II punishment) refers to the removal or withholding of a pleasant factor.', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'In the behavioral sciences, the terms positive and negative refer, when used in their strict technical sense, to the nature of the action performed by the conditioner rather than to the responding operant''s evaluation of that action and its consequence(s). Positive actions are those that add a factor, be it pleasant or unpleasant, to the environment, whereas negative actions are those that remove or withhold from the environment a factor of either type. In turn, the strict sense of reinforcement refers only to reward-based conditioning; the introduction of unpleasant factors and the removal or withholding of pleasant factors are instead referred to as punishment, which when used in its strict sense thus stands in contradistinction to reinforcement. Thus, positive reinforcement refers to the addition of a pleasant factor, positive punishment (sometimes called Type I punishment) refers to the addition of an unpleasant factor, negative reinforcement refers to the removal or withholding of an unpleasant factor, and negative punishment (Type II punishment) refers to the removal or withholding of a pleasant factor.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement: Terminology', 'This usage is at odds with some non-technical usages of the four term combinations, especially in the case of the term negative reinforcement, which is often used to denote what technical parlance would describe as positive punishment, in that the non-technical usage interprets reinforcement as subsuming both reward and punishment and negative as referring to the responding operant''s perception that the factorwas unpleasant. By contrast, technical parlance would use the term negative reinforcement to describe encouragement of a given behavior by creating a scenario in which an unpleasant factor is or will be present but engaging in the behavior results in either escaping from that factor or preventing its occurrence, as in Martin Seligman''s experiment involving dogs learning to avoid electric shocks.', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'This usage is at odds with some non-technical usages of the four term combinations, especially in the case of the term negative reinforcement, which is often used to denote what technical parlance would describe as positive punishment, in that the non-technical usage interprets reinforcement as subsuming both reward and punishment and negative as referring to the responding operant''s perception that the factorwas unpleasant. By contrast, technical parlance would use the term negative reinforcement to describe encouragement of a given behavior by creating a scenario in which an unpleasant factor is or will be present but engaging in the behavior results in either escaping from that factor or preventing its occurrence, as in Martin Seligman''s experiment involving dogs learning to avoid electric shocks.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement: Overview', 'B. F. Skinner was a well-known and influential researcher who articulated many of the theoretical constructs of reinforcement and behaviorism. Skinner defined reinforcers according to the change in response strength (response rate) rather than to more subjective criteria, such as what is pleasurable or valuable to someone. Accordingly, activities, foods or items considered pleasant or enjoyable may not necessarily be reinforcing (because they produce no increase in the response preceding them). Stimuli, settings, and activities only fit the definition of reinforcers if the behavior that immediately precedes the potential reinforcer increases in similar situations in the future; for example, a child who receives a cookie when he or she asks for one. If the frequency of "cookie-requesting behavior" increases, the cookie can be seen as reinforcing "cookie-requesting behavior". If however, "cookie-requesting behavior" does not increase the cookie cannot be considered reinforcing. The sole criterion that determines if a stimulus is reinforcing is the change in probability of a behavior after administration of that potential reinforcer. Other theories may focus on additional factors such as whether the person expected a behavior to produce a given outcome, but in the behavioral theory, reinforcement is defined by an increased probability of a response.', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'B. F. Skinner was a well-known and influential researcher who articulated many of the theoretical constructs of reinforcement and behaviorism. Skinner defined reinforcers according to the change in response strength (response rate) rather than to more subjective criteria, such as what is pleasurable or valuable to someone. Accordingly, activities, foods or items considered pleasant or enjoyable may not necessarily be reinforcing (because they produce no increase in the response preceding them). Stimuli, settings, and activities only fit the definition of reinforcers if the behavior that immediately precedes the potential reinforcer increases in similar situations in the future; for example, a child who receives a cookie when he or she asks for one. If the frequency of "cookie-requesting behavior" increases, the cookie can be seen as reinforcing "cookie-requesting behavior". If however, "cookie-requesting behavior" does not increase the cookie cannot be considered reinforcing. The sole criterion that determines if a stimulus is reinforcing is the change in probability of a behavior after administration of that potential reinforcer. Other theories may focus on additional factors such as whether the person expected a behavior to produce a given outcome, but in the behavioral theory, reinforcement is defined by an increased probability of a response.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement: Overview', 'The study of reinforcement has produced an enormous body of reproducible experimental results. Reinforcement is the central concept and procedure in special education, applied behavior analysis, and the experimental analysis of behavior and is a core concept in some medical and psychopharmacology models, particularly addiction, dependence, and compulsion.', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'The study of reinforcement has produced an enormous body of reproducible experimental results. Reinforcement is the central concept and procedure in special education, applied behavior analysis, and the experimental analysis of behavior and is a core concept in some medical and psychopharmacology models, particularly addiction, dependence, and compulsion.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement: Operant conditioning', 'The term operant conditioning was introduced by Skinner to indicate that in his experimental paradigm, the organism is free to operate on the environment. In this paradigm, the experimenter cannot trigger the desirable response; the experimenter waits for the response to occur (to be emitted by the organism) and then a potential reinforcer is delivered. In the classical conditioning paradigm, the experimenter triggers (elicits) the desirable response by presenting a reflex eliciting stimulus, the unconditional stimulus (UCS), which they pair (precede) with a neutral stimulus, the conditional stimulus (CS). Reinforcement is a basic term in operant conditioning. For the punishment aspect of operant conditioning, see punishment (psychology).', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'The term operant conditioning was introduced by Skinner to indicate that in his experimental paradigm, the organism is free to operate on the environment. In this paradigm, the experimenter cannot trigger the desirable response; the experimenter waits for the response to occur (to be emitted by the organism) and then a potential reinforcer is delivered. In the classical conditioning paradigm, the experimenter triggers (elicits) the desirable response by presenting a reflex eliciting stimulus, the unconditional stimulus (UCS), which they pair (precede) with a neutral stimulus, the conditional stimulus (CS). Reinforcement is a basic term in operant conditioning. For the punishment aspect of operant conditioning, see punishment (psychology).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Reinforcement: Positive reinforcement', 'Positive reinforcement occurs when a desirable event or stimulus is presented as a consequence of a behavior and the chance that this behavior will manifest in similar environments increases. For example, if reading a book is fun, then experiencing the fun positively reinforces the behavior of reading fun books. The person who receives the positive reinforcement (i.e., who has fun reading the book) will read more books to have more fun. The high probability instruction (HPI) treatment is a behaviorist treatment based on the idea of positive reinforcement.', 'Wikipedia: Reinforcement', 'https://en.wikipedia.org/w/index.php?title=Reinforcement&oldid=1373619067', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Positive reinforcement occurs when a desirable event or stimulus is presented as a consequence of a behavior and the chance that this behavior will manifest in similar environments increases. For example, if reading a book is fun, then experiencing the fun positively reinforces the behavior of reading fun books. The person who receives the positive reinforcement (i.e., who has fun reading the book) will read more books to have more fun. The high probability instruction (HPI) treatment is a behaviorist treatment based on the idea of positive reinforcement.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning', 'Observational learning is learning that occurs through observing the behavior of others. It is a form of social learning which takes various forms, based on various processes. In humans, this form of learning seems to not need reinforcement to occur, but instead, requires a social model such as a parent, sibling, friend, or teacher with surroundings. Particularly in childhood, a model is someone of authority or higher status in an environment. In animals, observational learning is often based on classical conditioning, in which an instinctive behavior is elicited by observing the behavior of another (e.g. mobbing in birds), but other processes may be involved as well.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Observational learning is learning that occurs through observing the behavior of others. It is a form of social learning which takes various forms, based on various processes. In humans, this form of learning seems to not need reinforcement to occur, but instead, requires a social model such as a parent, sibling, friend, or teacher with surroundings. Particularly in childhood, a model is someone of authority or higher status in an environment. In animals, observational learning is often based on classical conditioning, in which an instinctive behavior is elicited by observing the behavior of another (e.g. mobbing in birds), but other processes may be involved as well.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning: Human', 'Many behaviors that a learner observes, remembers, and imitates are actions that models display and display modeling, even though the model may not intentionally try to instill a particular behavior. A child may learn to swear, smack, smoke, and deem other inappropriate behavior acceptable through poor modeling. Albert Bandura claims that children continually learn desirable and undesirable behavior through observational learning. Observational learning suggests that an individual''s environment, cognition, and behavior all incorporate and ultimately determine how the individual functions and models. Through observational learning, individual behaviors can spread across a culture through a process called diffusion chain. This basically occurs when an individual first learns a behavior by observing another individual and that individual serves as a model through whom other individuals learn the behavior, and so on. Culture plays a role in whether observational learning is the dominant learning style in a person or community. Some cultures expect children to actively participate in their communities and are therefore exposed to different trades and roles on a daily basis. This exposure allows children to observe and learn the different skills and practices that are valued in their communities.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Many behaviors that a learner observes, remembers, and imitates are actions that models display and display modeling, even though the model may not intentionally try to instill a particular behavior. A child may learn to swear, smack, smoke, and deem other inappropriate behavior acceptable through poor modeling. Albert Bandura claims that children continually learn desirable and undesirable behavior through observational learning. Observational learning suggests that an individual''s environment, cognition, and behavior all incorporate and ultimately determine how the individual functions and models. Through observational learning, individual behaviors can spread across a culture through a process called diffusion chain. This basically occurs when an individual first learns a behavior by observing another individual and that individual serves as a model through whom other individuals learn the behavior, and so on. Culture plays a role in whether observational learning is the dominant learning style in a person or community. Some cultures expect children to actively participate in their communities and are therefore exposed to different trades and roles on a daily basis. This exposure allows children to observe and learn the different skills and practices that are valued in their communities.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning: Human', 'Albert Bandura, who is known for the classic Bobo doll experiment, identified this basic form of learning in 1961. The importance of observational learning lies in helping individuals, especially children, acquire new responses by observing others'' behavior. Albert Bandura states that people''s behavior could be determined by their environment. Observational learning occurs through observing negative and positive behaviors. Bandura believes in reciprocal determinism in which the environment can influence people''s behavior and vice versa. For instance, the Bobo doll experiment shows that the model, in a determined environment, affects children''s behavior. In this experiment Bandura demonstrates that one group of children placed in an aggressive environment would act the same way, while the control group and the other group of children placed in a passive role model environment hardly shows any type of aggression.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Albert Bandura, who is known for the classic Bobo doll experiment, identified this basic form of learning in 1961. The importance of observational learning lies in helping individuals, especially children, acquire new responses by observing others'' behavior. Albert Bandura states that people''s behavior could be determined by their environment. Observational learning occurs through observing negative and positive behaviors. Bandura believes in reciprocal determinism in which the environment can influence people''s behavior and vice versa. For instance, the Bobo doll experiment shows that the model, in a determined environment, affects children''s behavior. In this experiment Bandura demonstrates that one group of children placed in an aggressive environment would act the same way, while the control group and the other group of children placed in a passive role model environment hardly shows any type of aggression.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning: Human', 'In communities where children''s primary mode of learning is through observation, the children are rarely separated from adult activities. This incorporation into the adult world at an early age allows children to use observational learning skills in multiple spheres of life. This learning through observation requires keen attentive abilities. Culturally, they learn that their participation and contributions are valued in their communities. This teaches children that it is their duty, as members of the community, to observe others'' contributions so they gradually become involved and participate further in the community.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'In communities where children''s primary mode of learning is through observation, the children are rarely separated from adult activities. This incorporation into the adult world at an early age allows children to use observational learning skills in multiple spheres of life. This learning through observation requires keen attentive abilities. Culturally, they learn that their participation and contributions are valued in their communities. This teaches children that it is their duty, as members of the community, to observe others'' contributions so they gradually become involved and participate further in the community.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning: Influential stages and factors', 'The stages of observational learning include exposure to the model, acquiring the model''s behaviour and accepting it as one''s own. Bandura''s social cognitive learning theory states that there are four factors that influence observational learning: Attention: Observers cannot learn unless they pay attention to what''s happening around them. This process is influenced by characteristics of the model, such as how much one likes or identifies with the model, and by characteristics of the observer, such as the observer''s expectations or level of emotional arousal. Retention/Memory: Observers must not only recognize the observed behavior but also remember it at some later time. This process depends on the observer''s ability to code or structure the information in an easily remembered form or to mentally or physically rehearse the model''s actions. Initiation/Motor: Observers must be physically and/intellectually capable of producing the act. In many cases, the observer possesses the necessary responses. But sometimes, reproducing the model''s actions may involve skills the observer has not yet acquired. It is one thing to carefully watch a circus juggler, but it is quite another to go home and repeat those acts.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'The stages of observational learning include exposure to the model, acquiring the model''s behaviour and accepting it as one''s own. Bandura''s social cognitive learning theory states that there are four factors that influence observational learning: Attention: Observers cannot learn unless they pay attention to what''s happening around them. This process is influenced by characteristics of the model, such as how much one likes or identifies with the model, and by characteristics of the observer, such as the observer''s expectations or level of emotional arousal. Retention/Memory: Observers must not only recognize the observed behavior but also remember it at some later time. This process depends on the observer''s ability to code or structure the information in an easily remembered form or to mentally or physically rehearse the model''s actions. Initiation/Motor: Observers must be physically and/intellectually capable of producing the act. In many cases, the observer possesses the necessary responses. But sometimes, reproducing the model''s actions may involve skills the observer has not yet acquired. It is one thing to carefully watch a circus juggler, but it is quite another to go home and repeat those acts.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning: Influential stages and factors', 'Bandura clearly distinguishes between learning and performance. Unless motivated, a person does not produce learned behavior. This motivation can come from external reinforcement, such as the experimenter''s promise of reward in some of Bandura''s studies, or the bribe of a parent. Or it can come from vicarious reinforcement, based on the observation that models are rewarded. High-status models can affect performance through motivation. For example, girls aged 11 to 14 performed better on a motor performance task when they thought it was demonstrated by a high-status cheerleader than by a low-status model. Some have even added a step between attention and retention involving encoding a behavior. Observational learning leads to a change in an individual''s behavior along three dimensions: An individual thinks about a situation in a different way and may have incentive to react to it. The change is a result of a person''s direct experiences as opposed to being in-born. For the most part, the change an individual has made is permanent.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Bandura clearly distinguishes between learning and performance. Unless motivated, a person does not produce learned behavior. This motivation can come from external reinforcement, such as the experimenter''s promise of reward in some of Bandura''s studies, or the bribe of a parent. Or it can come from vicarious reinforcement, based on the observation that models are rewarded. High-status models can affect performance through motivation. For example, girls aged 11 to 14 performed better on a motor performance task when they thought it was demonstrated by a high-status cheerleader than by a low-status model. Some have even added a step between attention and retention involving encoding a behavior. Observational learning leads to a change in an individual''s behavior along three dimensions: An individual thinks about a situation in a different way and may have incentive to react to it. The change is a result of a person''s direct experiences as opposed to being in-born. For the most part, the change an individual has made is permanent.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning: Effect on behavior', 'According to Bandura''s social cognitive learning theory, observational learning can affect behavior in many ways, with both positive and negative consequences. It can teach completely new behaviors, for one. It can also increase or decrease the frequency of behaviors that have previously been learned. Observational learning can even encourage behaviors that were previously forbidden (for example, the violent behavior towards the Bobo doll that children imitated in Albert Bandura''s study). Observational learning can also influence behaviors that are similar to, but not identical to, the ones being modeled. For example, seeing a model excel at playing the piano may motivate an observer to play the saxophone.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'According to Bandura''s social cognitive learning theory, observational learning can affect behavior in many ways, with both positive and negative consequences. It can teach completely new behaviors, for one. It can also increase or decrease the frequency of behaviors that have previously been learned. Observational learning can even encourage behaviors that were previously forbidden (for example, the violent behavior towards the Bobo doll that children imitated in Albert Bandura''s study). Observational learning can also influence behaviors that are similar to, but not identical to, the ones being modeled. For example, seeing a model excel at playing the piano may motivate an observer to play the saxophone.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Observational learning: Age difference', 'Albert Bandura stressed that developing children learn from different social models, meaning that no two children are exposed to exactly the same modeling influence. From infancy to adolescence, they are exposed to various social models. A 2013 study found that a toddlers'' previous social familiarity with a model was not always necessary for learning and that they were also able to learn from observing a stranger demonstrating or modeling a new action to another stranger. It was once believed that babies could not imitate actions until the latter half of the first year. However, a number of studies now report that infants as young as seven days can imitate simple facial expressions. By the latter half of their first year, 9-month-old babies can imitate actions hours after they first see them. As they continue to develop, toddlers around age two can acquire important personal and social skills by imitating a social model. Deferred imitation is an important developmental milestone in a two-year-old, in which children not only construct symbolic representations but can also remember information. Unlike toddlers, children of elementary school age are less likely to rely on imagination to represent an experience. Instead, they can verbally describe the model''s behavior. Since this form of learning does not need reinforcement, it is more likely to occur regularly.', 'Wikipedia: Observational learning', 'https://en.wikipedia.org/w/index.php?title=Observational_learning&oldid=1378447419', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Albert Bandura stressed that developing children learn from different social models, meaning that no two children are exposed to exactly the same modeling influence. From infancy to adolescence, they are exposed to various social models. A 2013 study found that a toddlers'' previous social familiarity with a model was not always necessary for learning and that they were also able to learn from observing a stranger demonstrating or modeling a new action to another stranger. It was once believed that babies could not imitate actions until the latter half of the first year. However, a number of studies now report that infants as young as seven days can imitate simple facial expressions. By the latter half of their first year, 9-month-old babies can imitate actions hours after they first see them. As they continue to develop, toddlers around age two can acquire important personal and social skills by imitating a social model. Deferred imitation is an important developmental milestone in a two-year-old, in which children not only construct symbolic representations but can also remember information. Unlike toddlers, children of elementary school age are less likely to rely on imagination to represent an experience. Instead, they can verbally describe the model''s behavior. Since this form of learning does not need reinforcement, it is more likely to occur regularly.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory', 'Memory is the faculty of the mind by which data or information is encoded, stored, and retrieved when needed. It is the retention of information over time for the purpose of influencing future action. If past events could not be remembered, it would be impossible for language, relationships, or personal identity to develop. Memory loss is usually described as forgetfulness or a disorder such as amnesia. Memory is often understood as an information processing system with explicit and implicit functioning that is made up of a sensory processor, short-term (or working) memory, and long-term memory. This can be related to the neuron. The sensory processor allows information from the outside world to be sensed in the form of chemical and physical stimuli and attended to various levels of focus and intent. Working memory serves as an encoding and retrieval processor. Information in the form of stimuli is encoded in accordance with explicit or implicit functions by the working memory processor. The working memory also retrieves information from previously stored material. Finally, the function of long-term memory is to store information through various categorical models or systems.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Memory is the faculty of the mind by which data or information is encoded, stored, and retrieved when needed. It is the retention of information over time for the purpose of influencing future action. If past events could not be remembered, it would be impossible for language, relationships, or personal identity to develop. Memory loss is usually described as forgetfulness or a disorder such as amnesia. Memory is often understood as an information processing system with explicit and implicit functioning that is made up of a sensory processor, short-term (or working) memory, and long-term memory. This can be related to the neuron. The sensory processor allows information from the outside world to be sensed in the form of chemical and physical stimuli and attended to various levels of focus and intent. Working memory serves as an encoding and retrieval processor. Information in the form of stimuli is encoded in accordance with explicit or implicit functions by the working memory processor. The working memory also retrieves information from previously stored material. Finally, the function of long-term memory is to store information through various categorical models or systems.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory', 'Declarative, or explicit memory, is the conscious storage and recollection of data. Under declarative memory resides semantic and episodic memory. Semantic memory refers to memory that is encoded with specific meaning. Meanwhile, episodic memory refers to information that is encoded along a spatial and temporal plane. Declarative memory is usually the primary process thought of when referencing memory. Non-declarative, or implicit, memory is the unconscious storage and recollection of information. An example of a non-declarative process would be the unconscious learning or retrieval of information by way of procedural memory, or a priming phenomenon. Priming is the process of subliminally arousing specific responses from memory and shows that not all memory is consciously activated, whereas procedural memory is the slow and gradual learning of skills that often occurs without conscious attention to learning.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Declarative, or explicit memory, is the conscious storage and recollection of data. Under declarative memory resides semantic and episodic memory. Semantic memory refers to memory that is encoded with specific meaning. Meanwhile, episodic memory refers to information that is encoded along a spatial and temporal plane. Declarative memory is usually the primary process thought of when referencing memory. Non-declarative, or implicit, memory is the unconscious storage and recollection of information. An example of a non-declarative process would be the unconscious learning or retrieval of information by way of procedural memory, or a priming phenomenon. Priming is the process of subliminally arousing specific responses from memory and shows that not all memory is consciously activated, whereas procedural memory is the slow and gradual learning of skills that often occurs without conscious attention to learning.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory', 'Memory is not a perfect processor and is affected by many factors. The ways by which information is encoded, stored, and retrieved can all be corrupted. Pain, for example, has been identified as a physical condition that impairs memory, and has been noted in animal models as well as chronic pain patients. The amount of attention given new stimuli can diminish the amount of information that becomes encoded for storage. Also, the storage process can become corrupted by physical damage to areas of the brain that are associated with memory storage, such as the hippocampus. Finally, the retrieval of information from long-term memory can be disrupted because of decay within long-term memory. Normal functioning, decay over time, and brain damage all affect the accuracy and capacity of the memory.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Memory is not a perfect processor and is affected by many factors. The ways by which information is encoded, stored, and retrieved can all be corrupted. Pain, for example, has been identified as a physical condition that impairs memory, and has been noted in animal models as well as chronic pain patients. The amount of attention given new stimuli can diminish the amount of information that becomes encoded for storage. Also, the storage process can become corrupted by physical damage to areas of the brain that are associated with memory storage, such as the hippocampus. Finally, the retrieval of information from long-term memory can be disrupted because of decay within long-term memory. Normal functioning, decay over time, and brain damage all affect the accuracy and capacity of the memory.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory: Sensory memory', 'Sensory memory holds information, derived from the senses, less than one second after an item is perceived. The ability to look at an item and remember what it looked like with just a split second of observation, or memorization, is an example of sensory memory. It is out of cognitive control and is an automatic response. With very short presentations, participants often report that they seem to "see" more than they can actually report. The first precise experiments exploring this form of sensory memory were conducted by George Sperling (1963) using the "partial report paradigm." Subjects were presented with a grid of 12 letters, arranged into three rows of four. After a brief presentation, subjects were then played either a high, medium or low tone, cuing them which of the rows to report. Based on these partial report experiments, Sperling was able to show that the capacity of sensory memory was approximately 12 items, but that it degraded very quickly (within a few hundred milliseconds). Because this form of memory degrades so quickly, participants would see the display but be unable to report all of the items (12 in the "whole report" procedure) before they decayed. This type of memory cannot be prolonged via rehearsal.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Sensory memory holds information, derived from the senses, less than one second after an item is perceived. The ability to look at an item and remember what it looked like with just a split second of observation, or memorization, is an example of sensory memory. It is out of cognitive control and is an automatic response. With very short presentations, participants often report that they seem to "see" more than they can actually report. The first precise experiments exploring this form of sensory memory were conducted by George Sperling (1963) using the "partial report paradigm." Subjects were presented with a grid of 12 letters, arranged into three rows of four. After a brief presentation, subjects were then played either a high, medium or low tone, cuing them which of the rows to report. Based on these partial report experiments, Sperling was able to show that the capacity of sensory memory was approximately 12 items, but that it degraded very quickly (within a few hundred milliseconds). Because this form of memory degrades so quickly, participants would see the display but be unable to report all of the items (12 in the "whole report" procedure) before they decayed. This type of memory cannot be prolonged via rehearsal.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory: Sensory memory', 'Three types of sensory memories exist. Iconic memory is a fast decaying store of visual information, a type of sensory memory that briefly stores an image that has been perceived for a small duration. Echoic memory is a fast decaying store of auditory information, also a sensory memory that briefly stores sounds that have been perceived for short durations. Haptic memory is a type of sensory memory that represents a database for touch stimuli.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Three types of sensory memories exist. Iconic memory is a fast decaying store of visual information, a type of sensory memory that briefly stores an image that has been perceived for a small duration. Echoic memory is a fast decaying store of auditory information, also a sensory memory that briefly stores sounds that have been perceived for short durations. Haptic memory is a type of sensory memory that represents a database for touch stimuli.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory: Retrieval cues', 'How we encode information has a big impact on how well we remember it later. Research on levels of processing shows that memory is better when encoding emphasizes "deep" aspects of a stimulus (such as meaning) vs. "shallow" aspects of a stimulus (such as a place). "Deep" encoding leads to a highly distributed representation and "shallow" encoding leads to a sparse representation. Thinking about meaning creates a richer, more connected memory, while shallow processing leads to weaker, less lasting traces. Memory also works best when the cues we use to recall information match the ones present during learning which connects to the principle called encoding specificity. Similarly, context dependence shows that remembering is easier when the environment at study matches the environment at test. For example, studying in a "wet" lab can help if the test is in the same setting. Overall, these findings show that both the way we think about information and the context in which we learn it play a major role in memory.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'How we encode information has a big impact on how well we remember it later. Research on levels of processing shows that memory is better when encoding emphasizes "deep" aspects of a stimulus (such as meaning) vs. "shallow" aspects of a stimulus (such as a place). "Deep" encoding leads to a highly distributed representation and "shallow" encoding leads to a sparse representation. Thinking about meaning creates a richer, more connected memory, while shallow processing leads to weaker, less lasting traces. Memory also works best when the cues we use to recall information match the ones present during learning which connects to the principle called encoding specificity. Similarly, context dependence shows that remembering is easier when the environment at study matches the environment at test. For example, studying in a "wet" lab can help if the test is in the same setting. Overall, these findings show that both the way we think about information and the context in which we learn it play a major role in memory.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory: Short-term memory', 'Short-term memory, not to be confused with working memory, allows recall for a period of several seconds to a minute without rehearsal. Its capacity, however, is very limited. In 1956, George A. Miller (1920–2012), when working at Bell Laboratories, conducted experiments showing that the store of short-term memory was 7±2 items. (Hence, the title of his famous paper, "The Magical Number 7±2.") Modern perspectives estimate the capacity of short-term memory to be lower, typically on the order of 4–5 items, or argue for a more flexible limit based on information instead of items. Memory capacity can be increased through a process called chunking. For example, in recalling a ten-digit telephone number, a person could chunk the digits into three groups: first, the area code (such as 123), then a three-digit chunk (456), and, last, a four-digit chunk (7890). This method of remembering telephone numbers is far more effective than attempting to remember a string of 10 digits; this is because we are able to chunk the information into meaningful groups of numbers. This is reflected in some countries'' tendencies to display telephone numbers as several chunks of two to four numbers.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Short-term memory, not to be confused with working memory, allows recall for a period of several seconds to a minute without rehearsal. Its capacity, however, is very limited. In 1956, George A. Miller (1920–2012), when working at Bell Laboratories, conducted experiments showing that the store of short-term memory was 7±2 items. (Hence, the title of his famous paper, "The Magical Number 7±2.") Modern perspectives estimate the capacity of short-term memory to be lower, typically on the order of 4–5 items, or argue for a more flexible limit based on information instead of items. Memory capacity can be increased through a process called chunking. For example, in recalling a ten-digit telephone number, a person could chunk the digits into three groups: first, the area code (such as 123), then a three-digit chunk (456), and, last, a four-digit chunk (7890). This method of remembering telephone numbers is far more effective than attempting to remember a string of 10 digits; this is because we are able to chunk the information into meaningful groups of numbers. This is reflected in some countries'' tendencies to display telephone numbers as several chunks of two to four numbers.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Memory: Short-term memory', 'Short-term memory is believed to rely mostly on an acoustic code for storing information, and to a lesser extent on a visual code. Conrad (1964) found that test subjects had more difficulty recalling collections of letters that were acoustically similar, e.g., E, P, D. Confusion with recalling acoustically similar letters rather than visually similar letters implies that the letters were encoded acoustically. Conrad''s (1964) study, however, deals with the encoding of written text. Thus, while the memory of written language may rely on acoustic components, generalizations to all forms of memory cannot be made.', 'Wikipedia: Memory', 'https://en.wikipedia.org/w/index.php?title=Memory&oldid=1380372913', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Short-term memory is believed to rely mostly on an acoustic code for storing information, and to a lesser extent on a visual code. Conrad (1964) found that test subjects had more difficulty recalling collections of letters that were acoustically similar, e.g., E, P, D. Confusion with recalling acoustically similar letters rather than visually similar letters implies that the letters were encoded acoustically. Conrad''s (1964) study, however, deals with the encoding of written text. Thus, while the memory of written language may rely on acoustic components, generalizations to all forms of memory cannot be made.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory', 'Long-term memory (LTM) is the stage of the Atkinson–Shiffrin memory model in which informative knowledge is held indefinitely. It is defined in contrast to sensory memory, the initial stage, and short-term or working memory, the second stage, which persists for about 18 to 30 seconds. LTM is grouped into two categories known as explicit memory (declarative memory) and implicit memory (non-declarative memory). Explicit memory is broken down into episodic and semantic memory, while implicit memory includes procedural memory and emotional conditioning.', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Long-term memory (LTM) is the stage of the Atkinson–Shiffrin memory model in which informative knowledge is held indefinitely. It is defined in contrast to sensory memory, the initial stage, and short-term or working memory, the second stage, which persists for about 18 to 30 seconds. LTM is grouped into two categories known as explicit memory (declarative memory) and implicit memory (non-declarative memory). Explicit memory is broken down into episodic and semantic memory, while implicit memory includes procedural memory and emotional conditioning.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory: Stores', 'The idea of separate memories for short- and long-term storage originated in the 19th century. One model of memory developed in the 1960s assumed that all memories are formed in one store and transfer to another store after a small period of time. This model is referred to as the "modal model", most famously detailed by Shiffrin. The model states that memory is first stored in sensory memory, which has a large capacity but can only maintain information for milliseconds. A representation of that rapidly decaying memory is moved to short-term memory. Short-term memory does not have a large capacity like sensory memory but holds information for seconds or minutes. The final storage is long-term memory, which has a very large capacity and is capable of holding information possibly for a lifetime. The exact mechanisms by which this transfer takes place, whether all or only some memories are retained permanently, and even to have the existence of a genuine distinction between stores, remain controversial.', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'The idea of separate memories for short- and long-term storage originated in the 19th century. One model of memory developed in the 1960s assumed that all memories are formed in one store and transfer to another store after a small period of time. This model is referred to as the "modal model", most famously detailed by Shiffrin. The model states that memory is first stored in sensory memory, which has a large capacity but can only maintain information for milliseconds. A representation of that rapidly decaying memory is moved to short-term memory. Short-term memory does not have a large capacity like sensory memory but holds information for seconds or minutes. The final storage is long-term memory, which has a very large capacity and is capable of holding information possibly for a lifetime. The exact mechanisms by which this transfer takes place, whether all or only some memories are retained permanently, and even to have the existence of a genuine distinction between stores, remain controversial.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory: Anterograde amnesia', 'One form of evidence cited in favor of the existence of a short-term store comes from anterograde amnesia, the inability to learn new facts and episodes. Patients with this form of amnesia have an intact ability to retain small amounts of information over short time scales (up to 30 seconds) but have little ability to form longer-term memories (illustrated by patient HM). This is interpreted as showing that the short-term store is protected from damage and diseases.', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'One form of evidence cited in favor of the existence of a short-term store comes from anterograde amnesia, the inability to learn new facts and episodes. Patients with this form of amnesia have an intact ability to retain small amounts of information over short time scales (up to 30 seconds) but have little ability to form longer-term memories (illustrated by patient HM). This is interpreted as showing that the short-term store is protected from damage and diseases.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory: Distraction tasks', 'Other evidence comes from experimental studies showing that some manipulations impair memory for the 3 to 5 most recently learned words of a list (it is presumed that they are held in short-term memory). Recall for words from earlier in the list (it is presumed, stored in long-term memory) are unaffected. Other manipulations (e.g., semantic similarity of the words) affect only memory for earlier list words, but do not affect memory for the most recent few words. These results show that different factors affect short-term recall (disruption of rehearsal) and long-term recall (semantic similarity). Together, these findings show that long-term memory and short-term memory can vary independently of each other.', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Other evidence comes from experimental studies showing that some manipulations impair memory for the 3 to 5 most recently learned words of a list (it is presumed that they are held in short-term memory). Recall for words from earlier in the list (it is presumed, stored in long-term memory) are unaffected. Other manipulations (e.g., semantic similarity of the words) affect only memory for earlier list words, but do not affect memory for the most recent few words. These results show that different factors affect short-term recall (disruption of rehearsal) and long-term recall (semantic similarity). Together, these findings show that long-term memory and short-term memory can vary independently of each other.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory: Unitary model', 'Not all researchers agree that short- and long-term memory are separate systems. The alternative Unitary Model proposes that short-term memory consists of temporary activations of long-term representations (that there is one memory that behaves variously over all time scales, from milliseconds to years). It has been difficult to identify a sharp boundary between short- and long-term memory. Eugen Tarnow, a physics researcher, reported that the recall probability versus latency curve is a straight line from 6 to 600 seconds, with the probability of failure to recall only saturating after 600 seconds. If two different stores were operating in this time domain, it is reasonable to expect a discontinuity in this curve. Other research has shown that the detailed pattern of recall errors looks remarkably similar to recall of a list immediately after learning (it is presumed, from short-term memory) and recall after 24 hours (necessarily from long-term memory).', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Not all researchers agree that short- and long-term memory are separate systems. The alternative Unitary Model proposes that short-term memory consists of temporary activations of long-term representations (that there is one memory that behaves variously over all time scales, from milliseconds to years). It has been difficult to identify a sharp boundary between short- and long-term memory. Eugen Tarnow, a physics researcher, reported that the recall probability versus latency curve is a straight line from 6 to 600 seconds, with the probability of failure to recall only saturating after 600 seconds. If two different stores were operating in this time domain, it is reasonable to expect a discontinuity in this curve. Other research has shown that the detailed pattern of recall errors looks remarkably similar to recall of a list immediately after learning (it is presumed, from short-term memory) and recall after 24 hours (necessarily from long-term memory).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory: Unitary model', 'Further evidence for a unified store comes from experiments involving continual distractor tasks. In 1974, Bjork and Whitten, psychology researchers, presented subjects with word pairs to remember; before and after each word pair, subjects performed a simple multiplication task for 12 seconds. After the final word-pair, subjects performed the multiplication distractor task for 20 seconds. They reported that the recency effect (the increased probability of recall of the last items studied) and the primacy effect (the increased probability of recall of the first few items) was sustained. These results are incompatible with a separate short-term memory as the distractor items should have displaced some of the word-pairs in the buffer, thereby weakening the associated strength of the items in long-term memory.', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Further evidence for a unified store comes from experiments involving continual distractor tasks. In 1974, Bjork and Whitten, psychology researchers, presented subjects with word pairs to remember; before and after each word pair, subjects performed a simple multiplication task for 12 seconds. After the final word-pair, subjects performed the multiplication distractor task for 20 seconds. They reported that the recency effect (the increased probability of recall of the last items studied) and the primacy effect (the increased probability of recall of the first few items) was sustained. These results are incompatible with a separate short-term memory as the distractor items should have displaced some of the word-pairs in the buffer, thereby weakening the associated strength of the items in long-term memory.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory: Unitary model', 'Ovid Tzeng (1973) reported an instance where the recency effect in free recall did not seem to result from a short-term memory store. Subjects were presented with four study-test periods of 10-word lists, with a continual distractor task (20-second period of counting-backward). At the end of each list, participants had to free recall as many words as possible. After recall of the fourth list, participants were asked to recall items from all four lists. Both the initial and final recall showed a recency effect. These results violated the predictions of a short-term memory model, where no recency effect would be expected.', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Ovid Tzeng (1973) reported an instance where the recency effect in free recall did not seem to result from a short-term memory store. Subjects were presented with four study-test periods of 10-word lists, with a continual distractor task (20-second period of counting-backward). At the end of each list, participants had to free recall as many words as possible. After recall of the fourth list, participants were asked to recall items from all four lists. Both the initial and final recall showed a recency effect. These results violated the predictions of a short-term memory model, where no recency effect would be expected.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Long-term memory: Unitary model', 'Koppenaal and Glanzer (1990) attempted to explain these phenomena as a result of the subjects'' adaptation to the distractor task, which allowed them to preserve at least some short-term memory capabilities. In their experiment, the long-term recency effect disappeared when the distractor after the last item differed from the distractors that preceded and followed the other items (e.g., arithmetic distractor task and word reading distractor task). Thapar and Greene challenged this theory. In one of their experiments, participants were given a different distractor task after every study item. According to Koppenaal and Glanzer''s theory, no recency effect would be expected as subjects would not have had time to adapt to the distractor; yet such a recency effect remained in place in the experiment.', 'Wikipedia: Long-term memory', 'https://en.wikipedia.org/w/index.php?title=Long-term_memory&oldid=1373002971', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Koppenaal and Glanzer (1990) attempted to explain these phenomena as a result of the subjects'' adaptation to the distractor task, which allowed them to preserve at least some short-term memory capabilities. In their experiment, the long-term recency effect disappeared when the distractor after the last item differed from the distractors that preceded and followed the other items (e.g., arithmetic distractor task and word reading distractor task). Thapar and Greene challenged this theory. In one of their experiments, participants were given a different distractor task after every study item. According to Koppenaal and Glanzer''s theory, no recency effect would be expected as subjects would not have had time to adapt to the distractor; yet such a recency effect remained in place in the experiment.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory', 'Working memory is a cognitive system with a limited capacity that can hold information temporarily. It is important for reasoning and the guidance of decision-making and behavior. Working memory is often used synonymously with short-term memory, but some theorists consider the two forms of memory distinct, assuming that working memory allows for the manipulation of stored information, whereas short-term memory only refers to the short-term storage of information. Working memory is a theoretical concept central to cognitive psychology, neuropsychology, and neuroscience.', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Working memory is a cognitive system with a limited capacity that can hold information temporarily. It is important for reasoning and the guidance of decision-making and behavior. Working memory is often used synonymously with short-term memory, but some theorists consider the two forms of memory distinct, assuming that working memory allows for the manipulation of stored information, whereas short-term memory only refers to the short-term storage of information. Working memory is a theoretical concept central to cognitive psychology, neuropsychology, and neuroscience.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory: Theories', 'Numerous models have been proposed for how working memory functions, both anatomically and cognitively. Of those, the two that have been most influential are summarized below.', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Numerous models have been proposed for how working memory functions, both anatomically and cognitively. Of those, the two that have been most influential are summarized below.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory: The multicomponent model', 'In 1974 Baddeley and Hitch introduced the multicomponent model of working memory. The theory proposed a model containing three components: the central executive, the phonological loop, and the visuospatial scratchpad with the central executive functioning as a control center of sorts, directing info between the phonological and visuospatial components. The central executive is responsible for, among other things, directing attention to relevant information, suppressing irrelevant information and inappropriate actions, and coordinating cognitive processes when more than one task is simultaneously performed. A "central executive" is responsible for supervising the integration of information and for coordinating subordinate systems responsible for the short-term maintenance of information. One subordinate system, the phonological loop (PL), stores phonological information (that is, the sound of language) and prevents its decay by continuously refreshing it in a rehearsal loop. It can, for example, maintain a seven-digit telephone number for as long as one repeats the number to oneself repeatedly. The other subordinate system, the visuospatial sketchpad, stores visual and spatial information. It can be used, for example, for constructing and manipulating visual images and for representing mental maps. Robert Logie proposed that the sketchpad can be further broken down into a visual subsystem (dealing with such phenomena as shape, colour, and texture) and a spatial subsystem (dealing with location). Evidence for this division has been mixed, although one study found the capacities of shape and spatial working memory to be mostly independent.', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'In 1974 Baddeley and Hitch introduced the multicomponent model of working memory. The theory proposed a model containing three components: the central executive, the phonological loop, and the visuospatial scratchpad with the central executive functioning as a control center of sorts, directing info between the phonological and visuospatial components. The central executive is responsible for, among other things, directing attention to relevant information, suppressing irrelevant information and inappropriate actions, and coordinating cognitive processes when more than one task is simultaneously performed. A "central executive" is responsible for supervising the integration of information and for coordinating subordinate systems responsible for the short-term maintenance of information. One subordinate system, the phonological loop (PL), stores phonological information (that is, the sound of language) and prevents its decay by continuously refreshing it in a rehearsal loop. It can, for example, maintain a seven-digit telephone number for as long as one repeats the number to oneself repeatedly. The other subordinate system, the visuospatial sketchpad, stores visual and spatial information. It can be used, for example, for constructing and manipulating visual images and for representing mental maps. Robert Logie proposed that the sketchpad can be further broken down into a visual subsystem (dealing with such phenomena as shape, colour, and texture) and a spatial subsystem (dealing with location). Evidence for this division has been mixed, although one study found the capacities of shape and spatial working memory to be mostly independent.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory: The multicomponent model', 'In 2000 Baddeley extended the model by adding a fourth component, the episodic buffer, which holds representations that integrate phonological, visual, and spatial information, and possibly information not covered by the subordinate systems (e.g., semantic information, musical information). The episodic buffer is also the link between working memory and long-term memory. The component is episodic because it is assumed to bind information into a unitary episodic representation. The episodic buffer resembles Tulving''s concept of episodic memory, but it differs in that the episodic buffer is a temporary store. It was renamed the awareness buffer in 2026. Episodic buffer can also serve as a bridge between working memory and long term memory. The way this happens is by integrating information from sources into a single representation. The episodic buffer takes the verbal, visual and the semantic information and combines it to temporarily stores it to be able to use that information. Which allows the individual(s) to take the current experience and the previous stored experience and uses that information in reading, language processing and problem solving. The episodic buffer also helps explain how information from separate working memory systems can be combined into meaningful episodes and supports complex cognitive tasks that require information from multiple memory task (Baddeley, A.D. 2000).', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'In 2000 Baddeley extended the model by adding a fourth component, the episodic buffer, which holds representations that integrate phonological, visual, and spatial information, and possibly information not covered by the subordinate systems (e.g., semantic information, musical information). The episodic buffer is also the link between working memory and long-term memory. The component is episodic because it is assumed to bind information into a unitary episodic representation. The episodic buffer resembles Tulving''s concept of episodic memory, but it differs in that the episodic buffer is a temporary store. It was renamed the awareness buffer in 2026. Episodic buffer can also serve as a bridge between working memory and long term memory. The way this happens is by integrating information from sources into a single representation. The episodic buffer takes the verbal, visual and the semantic information and combines it to temporarily stores it to be able to use that information. Which allows the individual(s) to take the current experience and the previous stored experience and uses that information in reading, language processing and problem solving. The episodic buffer also helps explain how information from separate working memory systems can be combined into meaningful episodes and supports complex cognitive tasks that require information from multiple memory task (Baddeley, A.D. 2000).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory: Working memory as part of long-term memory', 'Anders Ericsson and Walter Kintsch have introduced the notion of "long-term working memory", which they define as a set of "retrieval structures" in long-term memory that enable seamless access to the information relevant for everyday tasks. In this way, parts of long-term memory effectively function as working memory. In a similar vein, Cowan does not regard working memory as a separate system from long-term memory. Representations in working memory are a subset of representations in long-term memory. Working memory is organized into two embedded levels. The first consists of long-term memory representations that are activated. There can be many of these—there is theoretically no limit to the activation of representations in long-term memory. The second level is called the focus of attention. The focus is regarded as having a limited capacity and holds up to four of the activated representations.', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Anders Ericsson and Walter Kintsch have introduced the notion of "long-term working memory", which they define as a set of "retrieval structures" in long-term memory that enable seamless access to the information relevant for everyday tasks. In this way, parts of long-term memory effectively function as working memory. In a similar vein, Cowan does not regard working memory as a separate system from long-term memory. Representations in working memory are a subset of representations in long-term memory. Working memory is organized into two embedded levels. The first consists of long-term memory representations that are activated. There can be many of these—there is theoretically no limit to the activation of representations in long-term memory. The second level is called the focus of attention. The focus is regarded as having a limited capacity and holds up to four of the activated representations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory: Working memory as part of long-term memory', 'Oberauer has extended Cowan''s model by adding a third component—a more narrow focus of attention that holds only one chunk at a time. The one-element focus is embedded in the four-element focus and serves to select a single chunk for processing. For example, four digits can be held in mind at the same time in Cowan''s "focus of attention". When the individual wishes to perform a process on each of these digits—for example, adding the number two to each digit—separate processing is required for each digit since most individuals cannot perform several mathematical processes in parallel. Oberauer''s attentional component selects one of the digits for processing and then shifts the attentional focus to the next digit, continuing until all digits have been processed.', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Oberauer has extended Cowan''s model by adding a third component—a more narrow focus of attention that holds only one chunk at a time. The one-element focus is embedded in the four-element focus and serves to select a single chunk for processing. For example, four digits can be held in mind at the same time in Cowan''s "focus of attention". When the individual wishes to perform a process on each of these digits—for example, adding the number two to each digit—separate processing is required for each digit since most individuals cannot perform several mathematical processes in parallel. Oberauer''s attentional component selects one of the digits for processing and then shifts the attentional focus to the next digit, continuing until all digits have been processed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory: Capacity', 'Working memory is widely acknowledged as having limited capacity. An early quantification of the capacity limit associated with short-term memory was the "magical number seven" suggested by Miller in 1956. Miller claimed that the information-processing capacity of young adults is around seven elements, referred to as "chunks", regardless of whether the elements are digits, letters, words, or other units. Later research revealed this number depends on the category of chunks used (e.g., span may be around seven for digits, six for letters, and five for words), and even on features of the chunks within a category. For instance, attention span is lower for longer words than short words. In general, memory span for verbal contents (digits, letters, words, etc.) depends on the phonological complexity of the content (i.e., the number of phonemes, the number of syllables), and on the lexical status of the contents (whether the contents are words known to the person or not). Several other factors affect a person''s measured span, and therefore it is difficult to pin down the capacity of short-term or working memory to a number of chunks. Nonetheless, Cowan proposed that working memory has a capacity of about four chunks in young adults (and fewer in children and old adults).', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'Working memory is widely acknowledged as having limited capacity. An early quantification of the capacity limit associated with short-term memory was the "magical number seven" suggested by Miller in 1956. Miller claimed that the information-processing capacity of young adults is around seven elements, referred to as "chunks", regardless of whether the elements are digits, letters, words, or other units. Later research revealed this number depends on the category of chunks used (e.g., span may be around seven for digits, six for letters, and five for words), and even on features of the chunks within a category. For instance, attention span is lower for longer words than short words. In general, memory span for verbal contents (digits, letters, words, etc.) depends on the phonological complexity of the content (i.e., the number of phonemes, the number of syllables), and on the lexical status of the contents (whether the contents are words known to the person or not). Several other factors affect a person''s measured span, and therefore it is difficult to pin down the capacity of short-term or working memory to a number of chunks. Nonetheless, Cowan proposed that working memory has a capacity of about four chunks in young adults (and fewer in children and old adults).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'learning-memory', 'Working memory: Capacity', 'In the visual domain, some investigations report no fixed capacity limit with respect to the total number of items that can be held in working memory. Instead, the results argue for a limited resource that can be flexibly shared between items retained in memory (see below in Resource theories), with some items in the focus of attention being allocated more resource and recalled with greater precision.', 'Wikipedia: Working memory', 'https://en.wikipedia.org/w/index.php?title=Working_memory&oldid=1380417315', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'learning-memory' and body = 'In the visual domain, some investigations report no fixed capacity limit with respect to the total number of items that can be held in working memory. Instead, the results argue for a limited resource that can be flexibly shared between items retained in memory (see below in Resource theories), with some items in the focus of attention being allocated more resource and recalled with greater precision.');
